SC.launch=()=>`<div class="hd"><div><h2>Запуск и сервер в Казахстане</h2><p>Детские сады становятся лицензируемой деятельностью — данные детей и видео храним на сервере в Казахстане. Система ваша: код и база передаются вам, абонентской платы нет. Запуск — 4–6 недель от старта до работы обоих садов.</p></div></div>
 <div class="wid"><div><small>Срок</small><b class="a">4–6 недель</b><span>оба сада</span></div><div><small>Сервер</small><b style="font-size:15px">в Казахстане</b><span>выделенный, резервная копия каждую ночь</span></div><div><small>Перенос данных</small><b>1–2 дня</b><span>дети, родители, сотрудники из Excel</span></div><div><small>Обучение</small><b>1 день</b><span>на сад · воспитатели по видео-инструкции</span></div><div><small>Поддержка</small><b class="g">3 месяца</b><span>включена</span></div></div>
 <div class="tl">${[['Неделя 0','Демо → согласование','Проходим демо по экранам: «это нужно, это убрать, это иначе». Получается приложение № 1 к договору — состав системы. Дальше доплат за согласованное нет.','on'],['Недели 1–2','Ядро','Сады, группы, дети и родители, договоры, посещаемость, Face ID, роли. Импорт ваших списков. Приложение родителя и телефон воспитателя. Показ на ваших данных.',''],['Недели 3–4','Деньги и родители','Начисления и счета, Kaspi и выписки, долги, пакет для работодателей. Каналы групп и боты, дневник, запросы, CRM и бот из рекламы.',''],['Недели 5–6','Обучение, питание, документы, камеры','Циклограммы, мониторинг, кружки, меню и склад, база документов, самооценка к лицензированию, ЭЦП, видеостена и трансляции, AI-ассистент и сказки. Обучение, запуск обоих садов.',''],['После','Пилот AI-видео и 1С','По решению: пилот распознавания событий на 2 камерах; интеграция с 1С.','']].map(x=>`<div class="tli ${x[3]}"><span class="who">${x[0]}</span><b>${x[1]}</b><p>${x[2]}</p></div>`).join('')}</div>
 <div class="g3" style="margin-top:12px"><div class="pan"><h3>Расходы после запуска · не нам</h3><div class="kv"><span>Сервер в Казахстане с видеоархивом</span><b>≈ 30 000 ₸/мес</b></div><div class="kv"><span>WhatsApp</span><b>по тарифу провайдера</b></div><div class="kv"><span>Telegram</span><b>бесплатно</b></div></div><div class="pan"><h3>Что остаётся у вас</h3><p>Исходный код, база данных, доступы к серверу. Можно развивать своими силами или с нами — вы не привязаны.</p></div>${said('«Я очень сильно боюсь, что кто-то в техзадании важное забудет, а потом надо будет менять систему заново».','Платон: «Мы сделаем демо и утвердим с вами весь функционал прежде чем приступать. Доработки внутри договорённых пунктов — без дополнительной оплаты».')}</div>`;
/* ====== КАРТОЧКИ ====== */
const CARD={};
CARD.kid=id=>{const k=K_(id);const g=G_(k.grp);return [esc(k.n)+' '+attTag(k),`${ageOf(k)} ${plural(ageOf(k),['год','года','лет'])} · ${esc(SAD(k.sad).n)} · «${esc(g.n)}»`,
 `<div class="kv"><span>Родитель</span><b>${esc(k.par)}</b></div><div class="kv"><span>Сегодня</span><b>${esc(k.by)}</b></div><div class="kv"><span>Аллергия</span><b class="${k.alg!=='—'?'neg':''}">${esc(k.alg)}</b></div><div class="kv"><span>Тариф</span><b>${esc(TAR[k.tar].n)}</b></div><div class="kv"><span>Оплата</span><b>${payTag(k)} ${k.due?fmt(k.due)+' ₸':''}</b></div><p class="mini" style="margin-top:8px">Полная карточка — у ролей, которым она доступна.</p>`]};
CARD.group=id=>{const g=G_(id);const kids=KIDS.filter(k=>k.grp===id);return [`Группа «${esc(g.n)}»`,`${esc(SAD(g.sad).n)} · ${g.age} · ${esc(g.lvl)} · язык ${g.lang} · ${esc(g.room)}`,
 `<div class="wid" style="grid-template-columns:repeat(4,1fr)"><div><small>Мест</small><b>${g.cap}</b></div><div><small>Детей</small><b>${g.kids}</b></div><div><small>Сегодня</small><b class="g">${g.pres}</b></div><div><small>Болеют</small><b class="i">${g.sick}</b></div></div>
 <div class="kv"><span>Воспитатель</span><b>${esc(E_(g.t1).n)}</b></div><div class="kv"><span>Второй педагог</span><b>${esc(E_(g.t2).n)}</b></div><div class="kv"><span>Камера</span><b>${g.cam} · трансляция родителям</b></div><div class="kv"><span>Каналы</span><b>«${esc(g.n)} · Новости» + «${esc(g.n)} · Чат»</b></div>
 ${kids.length?`<h4 style="margin:12px 0 6px">Дети в выборке</h4>${kids.map(k=>`<div class="kv"><span>${esc(k.n)}</span><b>${attTag(k)}</b></div>`).join('')}`:''}
 <div class="btns" style="margin-top:10px"><button class="bt" onclick="closeM();curGrp='${id}';go('attendance')">Табель</button><button class="bt p" onclick="closeM();act('msg-group')">Сообщение родителям группы</button></div>`]};
CARD.staff=id=>{const e=E_(id);return [esc(e.n),`${esc(e.pos)} · ${esc(SAD(e.sad).n)}${e.grp?' · «'+esc(G_(e.grp).n)+'»':''}`,
 `<div class="kv"><span>Пришла сегодня · Face ID</span><b class="${e.late?'warnt':''}">${e.in||'—'}${e.late?' · опоздание '+e.late+' мин':''}</b></div><div class="kv"><span>Часов за сентябрь</span><b>${e.h||'—'} / ${e.plan||'—'}</b></div><div class="kv"><span>Категория</span><b>${esc(e.cat||'—')}</b></div><div class="kv"><span>Оклад</span><b>${e.rate?fmt(e.rate)+' ₸':'почасово'}</b></div><div class="kv"><span>Документы для лицензирования</span><b>${id==='E-25'?'<span class="neg">нет сертификата курсов</span>':'диплом, курсы, медкнижка — загружены'}</b></div>
 <div class="btns" style="margin-top:10px"><button class="bt" onclick="closeM();act('task-new')">Поставить задачу</button><button class="bt p" onclick="closeM();go('payroll')">Зарплата</button></div>`]};
CARD.pay=id=>{const p=PAY.find(x=>x.id===id);const k=p.kid?K_(p.kid):null;return [`Платёж ${esc(p.id)} <span class="tag ${PST[p.st][1]}">${PST[p.st][0]}</span>`,`${dl(p.d)} · ${PW[p.way]} · от «${esc(p.from)}»`,
 `<div class="wid" style="grid-template-columns:repeat(2,1fr)"><div><small>Сумма</small><b class="a">${tg(p.v)}</b></div><div><small>Ребёнок</small><b style="font-size:15px">${k?esc(k.n):'<span class="neg">не определён</span>'}</b></div></div>
 <div class="note" style="--tone:${p.st==='new'?'var(--bad)':'var(--brand)'}"><b>${p.st==='new'?'Нет договора в назначении':'Как разнесён'}</b><p>${esc(p.note)}</p></div>
 ${p.st==='new'?`<h4 style="margin:12px 0 6px">Подсказка системы</h4><div class="srow"><span>Мирас Утегенов · мама Райхан Утегенова · долг 95 000 ₸ · сумма совпадает</span><button class="bt p" onclick="closeM();act('pay-assign')">Это он</button></div>`:''}
 <div class="btns" style="margin-top:10px">${k?`<button class="bt" onclick="closeM();openKid('${k.id}')">Карточка ребёнка</button>`:''}${p.way==='emp'?`<button class="bt p" onclick="closeM();go('esf')">АВР и ЭСФ</button>`:''}</div>`]};
CARD.lead=id=>{const l=LEADS.find(x=>x.id===id);const f=FUN.find(x=>x.k===l.k);const nx=FUN[FUN.indexOf(f)+1];return [esc(l.n)+` <span class="tag" style="background:${f.c}1a;color:${f.c}">${esc(f.n)}</span>`,`${esc(l.par)} · ${esc(l.ph)} · ${esc(SAD(l.sad).n)} · ${dl(l.d)}`,
 `<div class="kv"><span>Источник</span><b>${esc(l.src)}</b></div><div class="kv"><span>Объявление</span><b>${esc(l.ad)}</b></div><div class="kv"><span>Возраст</span><b>${l.age}</b></div><div class="kv"><span>Свободные места этого возраста</span><b>${GRP.filter(g=>g.sad===l.sad&&g.age===l.age).reduce((a,g)=>a+g.cap-g.kids,0)||'нет · в очередь'}</b></div><div class="kv"><span>Следующий шаг</span><b>${esc(l.next)}</b></div>
 <div class="btns" style="margin-top:10px"><button class="bt" onclick="closeM();act('msg-lead')">Написать</button>${nx?`<button class="bt p" onclick="closeM();act('lead-move','${l.id}')">→ ${esc(nx.n)}</button>`:''}</div>`]};
CARD.emp=i=>{const e=EMPDOC[+i];return [esc(e.emp),`БИН ${e.bin} · ${e.kids.length} ${plural(e.kids.length,['ребёнок','ребёнка','детей'])} · сентябрь`,
 `${e.kids.map(k=>`<div class="kv"><span>${esc(K_(k).n)}</span><b>${fmt(feeOf(K_(k)))}</b></div>`).join('')}<div class="kv"><span><b>Счёт ${e.inv}</b></span><b>${fmt(e.sum)} ₸</b></div><div class="kv"><span>АВР</span><b>${esc(e.avr)}</b></div><div class="kv"><span>ЭСФ</span><b>${esc(e.esf)}</b></div>${e.note?`<div class="note" style="--tone:var(--warn)"><b>Внимание</b><p>${esc(e.note)}</p></div>`:''}
 <div class="btns" style="margin-top:10px"><button class="bt" onclick="closeM();act('doc-open')">Счёт PDF</button><button class="bt p" onclick="closeM();act('avr')">АВР на подпись</button></div>`]};
CARD.aiev=id=>{const e=AIEV.find(x=>x.id===id);return [`${esc(e.id)} · ${esc(e.type)} <span class="tag ${AIST[e.st][1]}">${AIST[e.st][0]}</span>`,`${dl(e.d)} ${e.t} · ${e.cam}${e.grp?' · «'+esc(G_(e.grp).n)+'»':''} · уверенность ${e.conf} %`,
 `<div class="vimg big"><svg viewBox="0 0 320 150" preserveAspectRatio="none"><rect width="320" height="150" fill="currentColor" opacity=".08"/><path d="M0 120 L80 90 L150 105 L220 70 L320 95 L320 150 L0 150Z" fill="currentColor" opacity=".12"/><rect x="120" y="40" width="80" height="70" fill="none" stroke="#c0392b" stroke-width="2" stroke-dasharray="5 3"/></svg><span class="live">● фрагмент 00:40</span><span class="ts mono">${dd(e.d)} ${e.t}</span></div>
 <div class="kv"><span>Кто проверил</span><b>${esc(e.who)}</b></div><div class="kv"><span>Итог</span><b>${esc(e.res)}</b></div><div class="kv"><span>Уведомлены</span><b>воспитатель группы, методист · через 20 сек</b></div>
 <div class="btns" style="margin-top:10px"><button class="bt" onclick="closeM();act('ai-false')">Ложное</button><button class="bt p" onclick="closeM();act('inc-new')">Создать инцидент</button></div>`]};
function card(k,id){const f=CARD[k];if(!f)return;let r;try{r=f(id)}catch(e){toast('Карточка не найдена: '+esc(k)+' · '+esc(id));return}const [t,s,b]=r;openM(t,s,b)}

/* ====== ДЕЙСТВИЯ ====== */
