let ti=-1,tRun=false;
function tour(){if(tRun){stopTour();return}tRun=true;ti=-1;document.getElementById('tourBtn').textContent='■';step()}
function step(){if(!tRun)return;ti++;if(ti>=TOUR.length){stopTour();toast('Сценарий показа закончен. Всё кликается: дети, группы, платежи, сотрудники, заявки, камеры.');return}const [k,m]=TOUR[ti];if(!allowed(k)){step();return}cur=k;if(k==='child'){curKid='K-01';kidTab='main'}if(k==='owner')curSad='all';build();toast(m);setTimeout(step,ti===0?6200:7200);}
function stopTour(){tRun=false;ti=-1;const b=document.getElementById('tourBtn');if(b)b.textContent='▶'}
(function(){renderRoles();applyTheme();const s=document.getElementById('rsel');if(s)s.addEventListener('change',e=>switchRole(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeM();stopTour()}});let q='',kk='';try{const u=new URLSearchParams(location.search);q=u.get('s')||'';kk=u.get('kid')||''}catch(e){}if(kk&&K_(kk))curKid=kk;if(q&&SECOF[q]){const r=Object.keys(ROLES).find(k=>ROLES[k].s.indexOf(q)>=0);if(r){cur=q;enter(r)}}})();
